function check(candidate) {
    console.assert(JSON.stringify(candidate([1,0,1,0,-1,0,1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([-1,0,0,0,0,1])) === JSON.stringify(4));
    console.assert(JSON.stringify(candidate([0,0,0,0,0,0,0])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([-1,0,0,1,0,0,-1])) === JSON.stringify(2));
    console.assert(JSON.stringify(candidate([1,-1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([0,0,0,0,0])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([-1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([0])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([1,0,-1,0,1,0,-1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([0,0,0,0])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([0,1,0,-1,0])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,-1,1,-1,1,-1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([-1,1,-1,1,-1,1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([0,0,1,-1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([0,1,0,-1,0,1,0])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,1,1,-1,-1,-1,1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([-1,0,-1,0,1,0,1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,0,0,0,0,-1])) === JSON.stringify(4));
    console.assert(JSON.stringify(candidate([1,0,1,0,-1,0,-1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([-1,0,0,0,0,0,0,1])) === JSON.stringify(6));
    console.assert(JSON.stringify(candidate([1,0,0,0,0,0,0,-1])) === JSON.stringify(6));
    console.assert(JSON.stringify(candidate([1,0,0,-1,0,0,0,0,1])) === JSON.stringify(4));
    console.assert(JSON.stringify(candidate([1,0,0,0,0,0,-1])) === JSON.stringify(5));
    console.assert(JSON.stringify(candidate([-1,0,0,0,0,0,1])) === JSON.stringify(5));
    console.assert(JSON.stringify(candidate([1])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([1,1,-1,-1,1,1])) === JSON.stringify(0));
